using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The MCP SDK instantiates this class per-invocation via DI,
/// so constructor parameters are resolved from the service container.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // The SDK resolves constructor args from the DI container.
    // Because we register a named HttpClient, it's injected here automatically.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get the current weather forecast for a US state.")]
    public async Task<string> GetForecast(
        [Description("Two-letter US state code, e.g. CA")] string state)
    {
        var url = $"https://api.weather.gov/points/39.7456,-97.0892"; // example endpoint
        var response = await _httpClient.GetFromJsonAsync<JsonElement>(url);
        return response.ToString();
    }

    [McpServerTool, Description("List active weather alerts for a US state.")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code, e.g. TX")] string state)
    {
        var alerts = await _httpClient.GetFromJsonAsync<JsonElement>(
            $"https://api.weather.gov/alerts/active?area={state}");
        return alerts.ToString();
    }
}

using McpServer;
using Microsoft.Extensions.DependencyInjection;
using ModelContextProtocol;

var builder = McpServerBuilder.ForStdioTransport();

// Register a named HttpClient that will be injected into WeatherTools
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.DefaultRequestHeaders.Add("User-Agent", "McpServer/1.0");
});

// Register tool class — the SDK discovers methods marked [McpServerTool]
builder.WithTools<WeatherTools>();

await using var server = builder.Build();
await server.RunAsync();

